#!/usr/bin/env python3
"""Trace parser for -finstrument-functions traces generated by src/trace.c."""

from __future__ import annotations

import os
import re
import subprocess
import sys
from dataclasses import dataclass, field
from typing import Dict, List, Optional, Tuple, Union

import plotly.graph_objects as go


_FUNCTION_NAME_CACHE: Dict[str, str] = {}
_FUNCTION_FILE_CACHE: Dict[str, str] = {}


@dataclass
class FunctionCall:
    """Represents one instrumented function call recorded in a trace.

    Attributes:
        function_address: Pointer value of the function being entered or exited.
        function_name: Human-readable function name resolved using addr2line.
        function_file: Source file defining this function, when resolved.
        thread_id: Thread identifier reported by the instrumentation code.
        start_time: Timestamp in microseconds when the function entry was observed.
        end_time: Timestamp in microseconds when the function exit was observed, if any.
        caller: Reference to the parent call, if known.
        called_functions: Nested calls that were entered while this function was active.
    """

    function_address: str
    function_name: str
    function_file: Optional[str] = None
    thread_id: int = 0
    start_time: int = 0
    end_time: Optional[int] = None
    caller: Optional["FunctionCall"] = None
    called_functions: List["FunctionCall"] = field(default_factory=list)

    def to_dict(self) -> dict:
        """Convert the call metadata into a serializable dictionary.

        Returns:
            A dictionary containing the call details and recursively nested calls.
        """
        return {
            "function_address": self.function_address,
            "function_name": self.function_name,
            "function_file": self.function_file,
            "thread_id": self.thread_id,
            "start_time": self.start_time,
            "end_time": self.end_time,
            "caller_name": self.caller.function_name if self.caller is not None else None,
            "called_functions": [child.to_dict() for child in self.called_functions],
        }


@dataclass
class CallTreeNode:
    """Aggregated node in the call tree built from instrumented function calls.

    Each node represents all occurrences of a function under the same parent in the
    call tree. The `call_count` indicates how many times that function was called from
    that parent, while the time fields include the total duration with and without the
    direct children of that node.
    """

    function_name: str
    function_file: Optional[str] = None
    function_address: str = ""
    call_count: int = 0
    total_cpu_time_including_children: int = 0
    total_cpu_time_excluding_children: int = 0
    parent: Optional["CallTreeNode"] = None
    children: List["CallTreeNode"] = field(default_factory=list)

    def to_dict(self) -> dict:
        """Serialize the aggregate node to a dictionary."""
        return {
            "function_name": self.function_name,
            "function_file": self.function_file,
            "function_address": self.function_address,
            "call_count": self.call_count,
            "total_cpu_time_including_children": self.total_cpu_time_including_children,
            "total_cpu_time_excluding_children": self.total_cpu_time_excluding_children,
            "children": [child.to_dict() for child in self.children],
        }


def _normalize_pointer(pointer: Union[str, int, None]) -> Optional[str]:
    """Normalize a pointer value so identical addresses are compared consistently.

    Actual pointer addresses are normalized to hexadecimal. Symbol names (for example,
    "pthread_join") are left unchanged and displayed directly.
    """
    if pointer is None:
        return None
    if isinstance(pointer, int):
        return hex(pointer)

    value = str(pointer).strip()
    if value == "0" or value == "0x0" or value == "(nil)":
        return "0x0"

    if re.fullmatch(r"0x?[0-9A-Fa-f]+", value):
        return "0x" + value.lstrip("0x").lower() if value.lower() != "0x0" else "0x0"

    return value


def get_function_name(pointer: Union[str, int, None], executable_path: str, name_cache: Optional[Dict[str, str]] = None, file_cache: Optional[Dict[str, str]] = None) -> Tuple[str, Optional[str]]:
    """Resolve a function pointer to both its symbol name and defining source file.

    If the trace entry contains a symbol name rather than an address (for example,
    "pthread_join" from a manually wrapped call), that name is returned directly and
    no addr2line lookup is attempted.
    """
    if name_cache is None:
        name_cache = _FUNCTION_NAME_CACHE
    if file_cache is None:
        file_cache = _FUNCTION_FILE_CACHE

    if pointer is None:
        return "<unknown>", None

    value = str(pointer).strip()
    if value == "0" or value == "0x0" or value == "(nil)":
        return "<unknown>", None

    if not re.fullmatch(r"0x?[0-9A-Fa-f]+", value):
        return value, None

    normalized_pointer = _normalize_pointer(value)
    if normalized_pointer in name_cache and normalized_pointer in file_cache:
        return name_cache[normalized_pointer], file_cache[normalized_pointer] if file_cache[normalized_pointer] != "<unknown>" else None

    if not executable_path:
        name_cache.setdefault(normalized_pointer, "<unknown>")
        file_cache.setdefault(normalized_pointer, "<unknown>")
        return "<unknown>", None

    try:
        result = subprocess.run(
            ["addr2line", "-f", "-e", executable_path, normalized_pointer],
            check=False,
            capture_output=True,
            text=True,
        )
        if result.returncode != 0 or not result.stdout.strip():
            function_name = "<unknown>"
            function_file = None
        else:
            lines = result.stdout.splitlines()
            function_name = lines[0].strip() if lines else "<unknown>"
            function_file = lines[1].strip() if len(lines) > 1 else None
            if not function_name or function_name in {"??", "??:0", "0"}:
                function_name = "<unknown>"
            if not function_file or function_file in {"??", "??:0"}:
                function_file = None
    except (FileNotFoundError, OSError):
        function_name = "<unknown>"
        function_file = None

    name_cache[normalized_pointer] = function_name
    file_cache[normalized_pointer] = function_file or "<unknown>"
    return function_name, function_file


def parse_line(line: str) -> dict:
    """Parse a single instrumentation record and return its fields.

    The trace format produced by src/trace.c is:
        e|x THREAD_ID CORE_ID FUNCTION_PTR CALLER_PTR TIMESTAMP_US

    Args:
        line: One raw line extracted from the trace log.

    Returns:
        A dictionary with the parsed event type, thread/core identifiers,
        addresses, and timestamp.

    Raises:
        ValueError: If the line is empty or does not match the expected format.
    """
    raw_line = (line or "").strip()
    if not raw_line:
        raise ValueError("Empty trace line")

    parts = raw_line.split()
    if len(parts) != 6:
        raise ValueError(f"Malformed trace line: '{line}'")

    event_type, thread_id, core_id, function_address, caller_address, timestamp_us = parts
    try:
        thread_id_value = int(thread_id)
        core_id_value = int(core_id)
        timestamp_value = int(timestamp_us)
    except ValueError as exc:
        raise ValueError(f"Invalid integer value in trace line: '{line}'") from exc

    return {
        "event": event_type,
        "thread_id": thread_id_value,
        "core_id": core_id_value,
        "function_address": function_address,
        "caller_address": caller_address,
        "timestamp_us": timestamp_value,
    }


def _call_duration(call: FunctionCall) -> int:
    """Return the duration of a call in microseconds, or 0 if it is incomplete."""
    if call.end_time is None or call.start_time is None:
        return 0
    return max(0, int(call.end_time) - int(call.start_time))


def analyze_call_tree(calls: List[FunctionCall]) -> List[CallTreeNode]:
    """Build an aggregated call tree from parsed function calls.

    Each node represents one function as it appears under a given parent in the tree.
    When the same function is called multiple times from the same parent, they are merged
    into a single aggregated node. The node stores:
        - call_count: number of calls to this function from this parent
        - total_cpu_time_including_children: total duration of all aggregated calls,
          including the time spent in nested callees
        - total_cpu_time_excluding_children: total duration after subtracting direct
          child time from the total duration of the function

    Args:
        calls: List of function calls returned by ``parse_trace``.

    Returns:
        A list of root nodes representing the top-level functions in the trace.
    """

    def get_or_create_child(parent: CallTreeNode, call: FunctionCall) -> CallTreeNode:
        """Find an existing child node for the given call or create a new one."""
        key = (call.function_name, call.function_file, call.function_address)
        for child in parent.children:
            if (child.function_name, child.function_file, child.function_address) == key:
                return child

        node = CallTreeNode(
            function_name=call.function_name,
            function_file=call.function_file,
            function_address=call.function_address,
            parent=parent,
        )
        parent.children.append(node)
        return node

    def populate(parent_node: CallTreeNode, call: FunctionCall) -> None:
        """Recursively populate the call tree with the given call and its children."""
        node = get_or_create_child(parent_node, call)
        node.call_count += 1
        duration = _call_duration(call)
        node.total_cpu_time_including_children += duration

        for child_call in call.called_functions:
            populate(node, child_call)

        child_total = sum(child.total_cpu_time_including_children for child in node.children)
        node.total_cpu_time_excluding_children = max(0, node.total_cpu_time_including_children - child_total)

    # Build the call tree by iterating over all calls and aggregating them under their respective parents.
    roots: List[CallTreeNode] = []
    seen_roots: Dict[Tuple[str, Optional[str], str], CallTreeNode] = {}

    for call in calls:
        if call.caller is None:
            key = (call.function_name, call.function_file, call.function_address)
            if key not in seen_roots:
                root = CallTreeNode(
                    function_name=call.function_name,
                    function_file=call.function_file,
                    function_address=call.function_address,
                    parent=None,
                )
                seen_roots[key] = root
                roots.append(root)
            root = seen_roots[key]
            root.call_count += 1
            root.total_cpu_time_including_children += _call_duration(call)
            for child_call in call.called_functions:
                populate(root, child_call)
            child_total = sum(child.total_cpu_time_including_children for child in root.children)
            root.total_cpu_time_excluding_children = max(0, root.total_cpu_time_including_children - child_total)

    # Do a root-to-leaf traversal to add a few stats to each node including :
    # - Average CPU time per call (including and excluding children)
    # - Percentage of total CPU time spent in this function (including and excluding children)
    # - Percentage of parent CPU time spent in this function (including and excluding children)
    for root in roots:
        def traverse(node: CallTreeNode, parent_incl_time: int, total_cpu_time: int) -> None:
            
            node.avg_cpu_time_including_children = node.total_cpu_time_including_children / node.call_count
            node.avg_cpu_time_excluding_children = node.total_cpu_time_excluding_children / node.call_count
            
            node.percent_of_parent_incl = (node.total_cpu_time_including_children / parent_incl_time) * 100
            node.percent_of_parent_excl = (node.total_cpu_time_excluding_children / parent_incl_time) * 100

            node.percent_of_total_incl = (node.total_cpu_time_including_children / total_cpu_time) * 100
            node.percent_of_total_excl = (node.total_cpu_time_excluding_children / total_cpu_time) * 100

            for child in node.children:
                traverse(child, node.total_cpu_time_including_children, total_cpu_time)

        traverse(root, root.total_cpu_time_including_children, sum(r.total_cpu_time_including_children for r in roots))


    return roots


def parse_trace(trace_file_path: str, executable_path: str) -> Tuple[List[FunctionCall], List[int]]:
    """Parse a trace file generated by src/trace.c and reconstruct function calls.

    The tracing code writes a record on function entry ("e") and function exit ("x").
    This function matches each exit with the corresponding entry for the same thread and
    address, then reconstructs the call nesting to produce a list of FunctionCall objects.

    Args:
        trace_file_path: Path to the raw trace log (.out file).
        executable_path: Path to the executable used to generate the trace.

    Returns:
        A tuple ``(calls, core_ids)`` where:
            - calls is the list of completed function-call objects,
            - core_ids is the sorted list of cores encountered in the trace.
    """
    if not os.path.isfile(trace_file_path):
        raise FileNotFoundError(f"Trace file not found: {trace_file_path}")
    if not os.path.isfile(executable_path):
        raise FileNotFoundError(f"Executable not found: {executable_path}")

    threads_stack: Dict[int, List[FunctionCall]] = {}
    completed_calls: List[FunctionCall] = []
    core_ids: set[int] = set()

    with open(trace_file_path, "r", encoding="utf-8", errors="replace") as trace_file:
        for raw_line in trace_file:
            if not raw_line.strip():
                continue

            try:
                entry = parse_line(raw_line)
            except ValueError:
                continue

            core_ids.add(entry["core_id"])
            event_type = entry["event"]
            thread_id = entry["thread_id"]
            function_address = entry["function_address"]
            caller_address = entry["caller_address"]
            timestamp_us = entry["timestamp_us"]

            function_name, function_file = get_function_name(function_address, executable_path)

            if event_type == "e":
                stack = threads_stack.setdefault(thread_id, [])
                parent = stack[-1] if stack else None
                call = FunctionCall(
                    function_address=function_address,
                    function_name=function_name,
                    function_file=function_file,
                    thread_id=thread_id,
                    start_time=timestamp_us,
                    caller=parent,
                )
                if parent is not None:
                    parent.called_functions.append(call)
                stack.append(call)

            elif event_type == "x":
                stack = threads_stack.get(thread_id, [])
                if not stack:
                    continue

                match_index = None
                for index in range(len(stack) - 1, -1, -1):
                    if stack[index].function_address == function_address:
                        match_index = index
                        break

                if match_index is None:
                    continue

                call = stack.pop(match_index)
                call.end_time = timestamp_us
                completed_calls.append(call)

                if not stack:
                    threads_stack.pop(thread_id, None)

    for thread_id, remaining_stack in threads_stack.items():
        for call in remaining_stack:
            if call.end_time is None:
                completed_calls.append(call)

    all_calls = sorted(completed_calls, key=lambda call: (call.start_time, call.thread_id))
    return all_calls, sorted(core_ids)


def print_call_tree(node: CallTreeNode, indent: int = 0) -> None:
    prefix = "  " * indent
    print(
        f"{prefix}{node.function_name} "
        f"calls={node.call_count} "
        f"incl={node.total_cpu_time_including_children}us "
        f"excl={node.total_cpu_time_excluding_children}us "
        f"avg_incl={node.avg_cpu_time_including_children:.2f}us "
        f"avg_excl={node.avg_cpu_time_excluding_children:.2f}us "
        f"pct_incl={node.percent_of_parent_incl:.2f}% "
        f"pct_excl={node.percent_of_parent_excl:.2f}% "
        f"pct_of_total_incl={node.percent_of_total_incl:.2f}% "
        f"pct_of_total_excl={node.percent_of_total_excl:.2f}%"
    )

    for child in node.children:
        print_call_tree(child, indent + 1)


def build_call_tree_rows(roots: Union[List[CallTreeNode], List[FunctionCall]]) -> List[dict]:
    """Flatten a call tree into a list of rows appropriate for a foldable table view.

    The function prepends classical tree markers such as `├──`, `└──`, and `│` to each
    function name to reflect the depth inside the hierarchy.
    """

    if roots and isinstance(roots[0], FunctionCall):
        roots = analyze_call_tree(roots)

    rows: List[dict] = []

    def walk(node: CallTreeNode, depth: int, parent_id: Optional[str], is_last: bool) -> str:
        row_id = f"row_{len(rows)}"
        prefix = ""
        if depth > 0:
            branch = "└── " if is_last else "├── "
            prefix = ("│   " * (depth - 1)) + branch
        display_name = f"{prefix}{node.function_name}"

        rows.append(
            {
                "row_id": row_id,
                "parent_id": parent_id,
                "depth": depth,
                "display_name": display_name,
                "function_name": node.function_name,
                "function_file": node.function_file,
                "function_address": node.function_address,
                "call_count": node.call_count,
                "total_cpu_time_including_children": node.total_cpu_time_including_children,
                "total_cpu_time_excluding_children": node.total_cpu_time_excluding_children,
                "avg_cpu_time_including_children": getattr(node, "avg_cpu_time_including_children", 0.0),
                "avg_cpu_time_excluding_children": getattr(node, "avg_cpu_time_excluding_children", 0.0),
                "percent_of_parent_incl": getattr(node, "percent_of_parent_incl", 0.0),
                "percent_of_parent_excl": getattr(node, "percent_of_parent_excl", 0.0),
                "percent_of_total_incl": getattr(node, "percent_of_total_incl", 0.0),
                "percent_of_total_excl": getattr(node, "percent_of_total_excl", 0.0),
                "has_children": bool(node.children),
            }
        )

        for index, child in enumerate(node.children):
            walk(child, depth + 1, row_id, index == len(node.children) - 1)

        return row_id

    for index, root in enumerate(roots):
        walk(root, 0, None, index == len(roots) - 1)

    return rows


def build_call_tree_dataframe(roots: Union[List[CallTreeNode], List[FunctionCall]]):
    """Return the flattened call tree as a plain pandas DataFrame.

    This is the simplest display that renders cleanly in a notebook and keeps the full
    table visible by default.
    """
    import pandas as pd

    if roots and isinstance(roots[0], FunctionCall):
        roots = analyze_call_tree(roots)

    rows = build_call_tree_rows(roots)
    columns = [
        "display_name",
        "call_count",
        "total_cpu_time_including_children",
        "total_cpu_time_excluding_children",
        "avg_cpu_time_including_children",
        "avg_cpu_time_excluding_children",
        "percent_of_parent_incl",
        "percent_of_parent_excl",
        "percent_of_total_incl",
        "percent_of_total_excl",
    ]

    if not rows:
        return pd.DataFrame(columns=columns).set_index("display_name")

    df = pd.DataFrame(rows)[columns].copy()
    df = df.set_index("display_name")

    for col in df.columns:
        if pd.api.types.is_float_dtype(df[col].dtype):
            df[col] = df[col].map(lambda x: round(float(x), 2))

    return df


def build_function_statistics_dataframe(calls: List[FunctionCall]):
    """Aggregate per-function timing statistics from the call tree.

    The statistics must be derived from the aggregated tree, not from raw call records.
    This ensures that repeated appearances of the same function throughout the profile are
    summed consistently and that their total percentages remain aligned with the main call
    tree totals.
    """
    import pandas as pd

    roots = analyze_call_tree(calls) if calls else []
    total_profile_time = sum(root.total_cpu_time_including_children for root in roots)
    stats: Dict[Tuple[str, Optional[str], str], dict] = {}

    def visit(node: CallTreeNode) -> None:
        key = (node.function_name, node.function_file, node.function_address)
        entry = stats.setdefault(
            key,
            {
                "function_name": node.function_name,
                "function_file": node.function_file,
                "function_address": node.function_address,
                "call_count": 0,
                "total_cpu_time_including_children": 0,
                "total_cpu_time_excluding_children": 0,
            },
        )

        entry["call_count"] += node.call_count
        entry["total_cpu_time_including_children"] += node.total_cpu_time_including_children
        entry["total_cpu_time_excluding_children"] += node.total_cpu_time_excluding_children

        for child in node.children:
            visit(child)

    for root in roots:
        visit(root)

    rows = []
    for entry in stats.values():
        call_count = entry["call_count"]
        incl_total = entry["total_cpu_time_including_children"]
        excl_total = entry["total_cpu_time_excluding_children"]

        rows.append(
            {
                "function_name": entry["function_name"],
                "function_file": entry["function_file"],
                "function_address": entry["function_address"],
                "call_count": call_count,
                "total_cpu_time_including_children": incl_total,
                "total_cpu_time_excluding_children": excl_total,
                "avg_cpu_time_including_children": incl_total / call_count if call_count else 0.0,
                "avg_cpu_time_excluding_children": excl_total / call_count if call_count else 0.0,
                "percent_of_total_incl": (incl_total / total_profile_time * 100) if total_profile_time else 0.0,
                "percent_of_total_excl": (excl_total / total_profile_time * 100) if total_profile_time else 0.0,
            }
        )

    df = pd.DataFrame(rows)
    if df.empty:
        return pd.DataFrame(
            columns=[
                "function_name",
                "function_file",
                "function_address",
                "call_count",
                "total_cpu_time_including_children",
                "total_cpu_time_excluding_children",
                "avg_cpu_time_including_children",
                "avg_cpu_time_excluding_children",
                "percent_of_total_incl",
                "percent_of_total_excl",
            ]
        ).set_index("function_name")

    df = df.set_index("function_name")
    for col in [
        "avg_cpu_time_including_children",
        "avg_cpu_time_excluding_children",
        "percent_of_total_incl",
        "percent_of_total_excl",
    ]:
        if col in df.columns:
            df[col] = df[col].map(lambda value: round(float(value), 2))

    return df


def build_boxplot(calls: List[FunctionCall], function_names: Optional[List[str]] = None) -> go.Figure:
    """Build a Plotly box plot of inclusive execution time per function.

    Each completed function call contributes one duration value, and durations are
    grouped by function name. The X axis is only used to spread the categories, while
    the Y axis shows the execution time distribution in microseconds.

    Args:
        calls: Parsed function calls.
        function_names: Optional list of function names to keep in the box plot.
    """
    selected = set(function_names) if function_names is not None else None
    durations_by_function: Dict[str, List[int]] = {}

    for call in calls:
        if call.end_time is None or call.start_time is None:
            continue
        key = call.function_name or "<unknown>"
        if selected is not None and key not in selected:
            continue
        duration = max(0, int(call.end_time) - int(call.start_time))
        durations_by_function.setdefault(key, []).append(duration)

    if not durations_by_function:
        return go.Figure()

    fig = go.Figure()
    for function_name in sorted(durations_by_function):
        fig.add_trace(
            go.Box(
                y=durations_by_function[function_name],
                name=function_name,
                boxpoints=False,
                marker_color="steelblue",
                line_color="navy",
                hovertemplate=(
                    f"<b>{function_name}</b><br>"
                    "duration: %{y} us<extra></extra>"
                ),
            )
        )

    fig.update_layout(
        title="Inclusive execution time distribution by function",
        xaxis_title="Function",
        yaxis_title="Execution time (us)",
        template="plotly_white",
        showlegend=False,
        hovermode="closest",
        margin={"t": 40, "l": 50, "r": 20, "b": 80},
    )
    return fig


def build_flamegraph(calls: List[FunctionCall]) -> go.Figure:
    """Build a Plotly flame graph from the parsed call tree.

    The flame graph uses inclusive CPU time as the size of each cell. Each node in the
    call tree becomes a rectangle, stacked according to the call hierarchy.

    Args:
        calls: Call objects returned by ``parse_trace``.

    Returns:
        A Plotly ``go.Figure`` containing the flame graph.
    """
    roots = analyze_call_tree(calls)

    labels: List[str] = []
    parents: List[str] = []
    values: List[int] = []
    custom_data: List[Tuple[int, int, int, float, float, float, float, float, float, str]] = []
    ids: List[str] = []

    def walk(node: CallTreeNode, parent_id: Optional[str] = None) -> None:
        # Plotly icicle nodes require globally unique IDs. In threaded traces, the same
        # function can legitimately appear multiple times under different branches (for
        # example, thread_wrapper called from main and from spawned pthreads). Using only
        # the function name/address would cause duplicate IDs and makes the flame graph
        # invalid/blank.
        node_id = f"{node.function_name}:{node.function_address or 'unknown'}:{parent_id or 'root'}:{len(ids)}"
        labels.append(node.function_name)
        ids.append(node_id)
        parents.append(parent_id or "")
        values.append(node.total_cpu_time_including_children)
        custom_data.append(
            (
                node.call_count,
                node.total_cpu_time_including_children,
                node.total_cpu_time_excluding_children,
                node.avg_cpu_time_including_children,
                node.avg_cpu_time_excluding_children,
                node.percent_of_parent_incl,
                node.percent_of_parent_excl,
                node.percent_of_total_incl,
                node.percent_of_total_excl,
                node.function_file or "unknown",
            )
        )

        for child in node.children:
            walk(child, node_id)

    for root in roots:
        walk(root)

    fig = go.Figure(
        go.Icicle(
            ids=ids,
            labels=labels,
            parents=parents,
            values=values,
            branchvalues="total",
            customdata=custom_data,
            hovertemplate=(
                "<b>%{label}</b><br>"
                "file: %{customdata[9]}<br>"
                "calls: %{customdata[0]}<br>"
                "inclusive time: %{customdata[1]} us<br>"
                "exclusive time: %{customdata[2]} us<br>"
                "avg incl: %{customdata[3]:.2f} us<br>"
                "avg excl: %{customdata[4]:.2f} us<br>"
                "parent incl: %{customdata[5]:.2f}%<br>"
                "parent excl: %{customdata[6]:.2f}%<br>"
                "total incl: %{customdata[7]:.2f}%<br>"
                "total excl: %{customdata[8]:.2f}%<extra></extra>"
            ),
            root_color="lightgrey",
            tiling={"pad": 3, "orientation": "v"},
        )
    )
    fig.update_layout(
        title="Function call flame graph (inclusive time)",
        margin={"t": 40, "l": 10, "r": 10, "b": 10},
        paper_bgcolor="white",
        plot_bgcolor="white",
        font={"size": 12},
    )
    fig.update_traces(hoverlabel={"namelength": 80})
    return fig


if __name__ == "__main__":
    import argparse

    parser = argparse.ArgumentParser(description="Parse a function instrumentation trace.")
    parser.add_argument("trace_file", help="Path to the trace file produced by trace.c")
    parser.add_argument("executable", help="Path to the executable used to generate the trace")
    args = parser.parse_args()

    try:
        calls, cores = parse_trace(args.trace_file, args.executable)
        print(f"core_ids={cores}")
        for call in calls:
            caller_name = call.caller.function_name if call.caller is not None else None
            file_info = f" [{call.function_file}]" if call.function_file else ""
            print(
                f"{call.function_name}{file_info} [{call.thread_id}] "
                f"start={call.start_time} end={call.end_time} "
                f"caller={caller_name}"
            )

        print("\nCall tree analysis:")
        roots = analyze_call_tree(calls)
        for root in roots:
            print_call_tree(root)
        
    except (BrokenPipeError, OSError):
        # This happens when the output is piped to a command like head, which closes
        # the pipe early. We exit cleanly without showing a traceback.
        try:
            sys.stdout.close()
        except Exception:
            pass
        raise SystemExit(0)
